css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .shaker { position: absolute; left: 36%; top: 4%; width: 28%; height: 40%; border-radius: 42% 42% 12% 12% / 34% 34% 8% 8%; background: linear-gradient(var(--accent-2), var(--accent)); transform-origin: 50% 100%; animation: salt-shake calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .shaker::after { content: ''; position: absolute; left: 20%; right: 20%; top: 6%; height: 22%; border-radius: 3px; background: color-mix(in srgb, #000 22%, var(--accent-2)); }
.loader i { position: absolute; top: 46%; width: 5%; height: 5%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: salt-fall calc(var(--loader-speed) * 1.2) ease-in infinite; }
.loader i:nth-of-type(1) { left: 40%; }
.loader i:nth-of-type(2) { left: 47%; animation-delay: calc(var(--loader-speed) * .2); }
.loader i:nth-of-type(3) { left: 54%; animation-delay: calc(var(--loader-speed) * .4); }
.loader i:nth-of-type(4) { left: 43%; animation-delay: calc(var(--loader-speed) * .6); }
.loader i:nth-of-type(5) { left: 51%; animation-delay: calc(var(--loader-speed) * .8); }
.loader .plate { position: absolute; left: 16%; right: 16%; bottom: 8%; height: 12%; border-radius: 50%; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 18%, var(--accent-2))); }
@keyframes salt-shake { 0%, 100% { transform: rotate(-16deg); } 50% { transform: rotate(16deg); } }
@keyframes salt-fall { 0% { opacity: 0; transform: translateY(0) scale(.6); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateY(340%) scale(1); } }
